// ==========================================
// 网格基础配置



export class GridCoord{
    gridX: number = 0;
    gridY: number = 0;
}

export class Point{
    x: number = 0;
    y: number = 0;
    
    set(x:number, y:number){
        this.x = x;
        this.y = y;
    }
}
// ==========================================
export const GRID_COLS = 6;
export const GRID_ROWS = 8;

// 逻辑格尺寸
export const TILE_W = 134; 
export const TILE_H = 67;  

// 图片原尺寸
export const TILE_IMG_W = 134;
export const TILE_IMG_H = 82;
// 泥土厚度
export const DIRT_HEIGHT = 15;

// 视觉 Y 轴偏移量：因为图片底部有泥土，需要整体上移半截泥土高度，让菱形中心对齐网格中心
export const TILE_VISUAL_OFFSET_Y = DIRT_HEIGHT / 2; 

// ==========================================
// 居中偏移量计算
// ==========================================
// 在 2.5D 下：
// 最左边：gridX = COLS - 1, gridY = 0，此时 x 为负最大
// 最右边：gridX = 0, gridY = ROWS - 1，此时 x 为正最大
// 为了让整个菱形居中，算出 x 的中心点，然后取反作为偏移
const CENTER_X = ((GRID_ROWS - 1) - (GRID_COLS - 1)) * (TILE_W / 4);
const OFFSET_X = -CENTER_X;

// 最上方：(0, 0) 时 y = 0
// 最下方：(COLS - 1, ROWS - 1) 时 y 为负最大
// 算出 y 的中心点，取反作为偏移
const CENTER_Y = -((GRID_COLS - 1) + (GRID_ROWS - 1)) * (TILE_H / 4);
const OFFSET_Y = -CENTER_Y;

export const MAP_PIXEL_W = (GRID_COLS + GRID_ROWS) * (TILE_W / 2);  // 938
export const MAP_PIXEL_H = (GRID_COLS + GRID_ROWS) * (TILE_H / 2);  // 469


export function gridToLocal(gridX: number, gridY: number ,out?: Point): Point {
    // gridY 增加往右下走，gridX 增加往左下走
    const x = (gridY - gridX) * (TILE_W / 2) + OFFSET_X;
    const y = -(gridX + gridY) * (TILE_H / 2) + OFFSET_Y;
    if(!out){
        out = new Point();
    }
    out.set(x,y);
    return out;
}


export function localToGrid(lx: number, ly: number, out?: GridCoord): GridCoord | null {
    // 1. 减去偏移量，还原到以地图最顶端为原点的相对像素
    const px = lx - OFFSET_X;
    const py = -(ly - OFFSET_Y); // 转回正数


    const diff = px / (TILE_W / 2);
    const sum = py / (TILE_H / 2);

    const gx = (sum - diff) / 2;
    const gy = (sum + diff) / 2;

    // 3. 必须用 Math.round 四舍五入，判定点在哪个菱形里
    const finalGx = Math.round(gx);
    const finalGy = Math.round(gy);

    // 4. 边界拦截
    if (finalGx < 0 || finalGx >= GRID_COLS || finalGy < 0 || finalGy >= GRID_ROWS) {
        return null;
    }
    if(!out){
        out = new GridCoord();
    }
    out.gridX = finalGx;
    out.gridY = finalGy;

    return out;
}

